// src/api/lingmai.ts
import request from '../utils/request'; 
import { nanoid } from 'nanoid';

// --- 1. 类型定义 ---
export interface FlatBlock {
  id: string;
  type: string;
  data: string;
  sortOrder?: string;
}

// --- 2. 核心转换逻辑 ---

/**
 * 🌟 拍平：将 Tiptap Tree 转换为后端扁平化 Blocks
 */
// src/api/lingmai.ts
const flattenTiptapJson = (doc: any): FlatBlock[] => {
  if (!doc || !doc.content) return [];

  // 🌟 修改：利用 map 的第二个参数 index 作为排序权重
  return doc.content.map((node: any, index: number) => {
    const attrs = { ...node.attrs };
    const blockId = attrs.id || nanoid(21);
    attrs.id = blockId; 

    return {
      id: blockId,
      type: node.type,
      sortOrder: index.toString(), // 🌟 关键：按顺序生成 "0", "1", "2"...
      data: JSON.stringify({
        attrs: attrs,
        content: node.content
      })
    };
  });
};

/**
 * 🌟 重组：将后端 Blocks 还原为 Tiptap Tree
 */
const rebuildTiptapJson = (blocks: any[]) => {
  return {
    type: 'doc',
    content: (blocks || []).map(b => {
      try {
        const parsedData = JSON.parse(b.data);
        return {
          type: b.type,
          attrs: { ...parsedData.attrs, id: b.id },
          content: parsedData.content
        };
      } catch (e) {
        console.error("块解析失败:", b);
        return { type: 'paragraph', content: [] };
      }
    })
  };
};

// --- 3. API 请求封装 ---
export const lingmaiApi = {

  /**
