    return request.delete(`/LingMaiPublish/notes/${noteId}/unpublish`, { silentError: true });
  },

  getQuota() {
    return request.get('/LingMai/quota');
  },


  // --- 在 lingmaiApi 对象内添加 ---

/**
 * 🌟 归档碎片：将碎片状态设为 Archived (3)，从活跃侧边栏消失
 */
archiveNote(noteId: string) {
  return request.patch(`/LingMai/notes/${noteId}/archive`);
},

/**
 * 🌟 还原碎片：将碎片状态设为 Active (0)，重新回到活跃侧边栏
 */
restoreNote(noteId: string) {
  return request.patch(`/LingMai/notes/${noteId}/restore`);
},

/**
 * 🌟 获取当前空间下的归档列表：用于归档库/回收站查看
 */
getArchivedNoteList(spaceId: string) {
  return request.get(`/LingMai/archived?spaceId=${spaceId}`);
},

/**
 * 🌟 (建议补充) 获取当前配额与审计数据
 */
getQuotaUsage() {
  return request.get('/LingMai/quota');
},

// src/api/lingmai.ts 内部


  async updateNoteContent(noteId: string, payload: {
    noteId: string;
    title: string;
    extraData: string; 
    tags: string[]; 
    rawContent?: any; // 接收前端传来的原始 Tiptap 树
    blocks?: FlatBlock[]; 
  }, silentError = false) {
    // 如果存在 rawContent，在这里将其拍平赋值给 blocks
    if (payload.rawContent) {
      payload.blocks = flattenTiptapJson(payload.rawContent);
      delete payload.rawContent; // 删掉原始树，不发给后端
    }

    // 发送请求，后端完美接收 [FromBody] NoteSyncDto
    return request.post('/LingMai/sync', payload, { silentError });
  },

  /**
   * 🌟 保留的老同步函数：现在它能安全地借道 updateNoteContent，且不会报错
   */
  async syncBlocks(noteId: string, tiptapDoc: any) {
    const blocks = flattenTiptapJson(tiptapDoc);
    return this.updateNoteContent(noteId, {
      noteId,
      title: '', 
      extraData: '[]', 
      tags: [], // 🌟 补上缺省的空标签数组，防止后端接收到 null
      blocks
    });
  },


};

