    color: '#059669',
    description: '城市、国家、大陆、建筑、遗迹、自然景观'
  },
  item: {
    label: '物品',
    icon: '📦',
    color: '#d97706',
    description: '武器、防具、道具、药水、消耗品、材料'
  },
  event: {
    label: '事件',
    icon: '📖',
    color: '#dc2626',
    description: '历史事件、战役、重大转折'
  },
  faction: {
    label: '派系',
    icon: '🏛️',
    color: '#8b5cf6',
    description: '势力、阵营、家族'
  },
  species: {
    label: '物种',
    icon: '🐉',
    color: '#f59e0b',
