}

// ===== API 响应类型 =====

export interface PaginatedResponse<T> {
  total: number
  items: T[]
}

export interface SessionSummary {
  id: number
  gameTitle: string
  gameIcon: string
  totalScore: number
  resultTitle: string | null
  resultIcon: string | null
  createdAt: string
}

export interface SessionDetail {
  id: number
  gameTitle: string
  gameIcon: string
  totalScore: number
  result: {
    title: string
    description: string
    icon: string
    image: string
  } | null
  createdAt: string
  questions: {
    id: number
    type: string
    text: string
    image: string
    selectedScore: number
    options: {
      id: number
      label: string
      value: number
      image: string
    }[]
  }[]
}

